urlset:
{%- for file in pages -%}
    {% if file.page and not file.page.is_link and file.src_uri != '404.md' and (file.page.abs_url or file.page.canonical_url) %}

         {% if file.page.canonical_url %}{{ file.page.canonical_url|e }}{% else %}{{ file.page.abs_url|e }}{% endif %}
         {% if file.page.update_date %}{{file.page.update_date}}{% endif %}

    {%- endif -%}
{% endfor %}
